    if (n >= 3) {
      r.maj = { ...r.maj, status: 'lost', lost_reason: 'Sans réponse', ...champs({ motif_perte: 'sans réponse', recontact_autorise: 'non' }) };
      if (email) r.courriel = mail('cloture-sans-reponse');
      r.page = 'Troisième essai : la demande est close (« sans réponse »)' + (email ? ', et un message de clôture courtois est parti.' : '.');
    } else {
      r.activite = { subject: 'Rappeler ' + (personne.name || vars.ref) + ' (essai ' + (n + 1) + ')', type: 'call', due_date: demain10().toISODate(), due_time: '10:00', deal_id: deal.id };
      if (n === 1 && email) r.courriel = mail('essai-appel-email');
      else if (n === 1 && tel) r.sms = { a: tel, texte: versGsm(rendre(MODELES['sms-essai-appel'].corps, vars)) };
      r.page = 'Noté (essai ' + n + '). ' + (n === 1 ? (email ? 'Un e-mail' : tel ? 'Un SMS' : 'Aucun message') + ' lui propose de nous rappeler. ' : '') + 'Tâche « Rappeler » créée pour demain 10 h.';
    }
    break;
  }
  case 'hors-cible':
    r.maj = { ...champs({ priorite: 'hors-cible', relance_sla_niveau: 9 }) };
    r.page = 'Classée « hors cible ». Le bouton de réorientation est dans l\'e-mail interne.';
    break;
  case 'envoyer-reorientation':
    if (email) { r.courriel = mail(String(champ(deal, 'zone')) === 'hors' ? 'reorientation-zone' : 'reorientation-service'); }
    r.maj = { status: 'lost', lost_reason: 'Hors cible', ...champs({ motif_perte: 'hors cible', recontact_autorise: 'non' }) };
    r.page = email ? 'La réponse de réorientation est partie depuis votre adresse.' : 'Pas d\'e-mail : merci d\'appeler la personne.';
    break;
  case 'offre-parler':
    r.maj = champs({ a_repondu: 'oui' });
    r.activite = { subject: 'Rappeler : souhaite parler de l\'offre', type: 'call', due_date: t.toISODate(), deal_id: deal.id };
    r.page = message('page-offre-parler', vars).texte;
    break;
  case 'offre-reporte':
    r.maj = { status: 'lost', lost_reason: 'Reporté', ...champs({ a_repondu: 'oui', motif_perte: 'reporté', recontact_autorise: 'oui' }) };
    r.page = message('page-offre-reporte', vars).texte;
    break;
  case 'offre-autre':
    r.maj = { status: 'lost', lost_reason: 'Attribué ailleurs', ...champs({ a_repondu: 'oui', motif_perte: 'attribué ailleurs', recontact_autorise: 'non' }) };
    r.page = message('page-offre-autre', vars).texte;
    break;
  case 'offre-clore':
    r.maj = { status: 'lost', lost_reason: 'Sans réponse', ...champs({ motif_perte: 'sans réponse' }) };
    r.page = 'Offre close (« sans réponse »).';
    break;
  case 'offre-prolonger':
    r.maj = champs({ date_offre: t.minus({ days: 21 }).toISODate(), relance_offre_etape: 3 });
    r.page = 'Offre gardée ouverte 30 jours de plus, sans nouvelle relance.';
    break;
  case 'avis-recu': r.maj = champs({ avis_recu: 'oui' }); r.page = 'Merci : avis noté.'; break;
  case 'reserves-levees': r.maj = champs({ reserves_levees: 'oui' }); r.page = 'Réserves levées : la demande d\'avis partira dans deux jours ouvrables.'; break;
  case 'photos-sans-nom': case 'photos-commune': case 'photos-temoignage': case 'photos-refus':
    r.maj = champs({ accord_publication: choix.replace('photos-', '') + ' (' + t.toISODate() + ')' });
    r.page = choix === 'photos-refus' ? 'C\'est noté : nous ne publierons rien. Merci de nous avoir répondu.' : 'Merci pour votre accord. Nous vous soumettrons le texte avant toute publication.';
    break;
  case 'entretien-passage':
    r.creer = { title: 'Passage de contrôle · ' + (personne.name || ''), person_id: personne.value, pipeline_id: IDS.pipeline_demandes, stage_id: IDS.etape_nouvelle,
      user_id: IDS.utilisateur_terrain, ...champs({ priorite: 'B', canal: 'site', source: 'client-existant' }) };
    r.page = 'Merci. ' + (associe || 'Nous') + ' vous appelle dans les prochains jours ouvrables pour convenir d\'un passage.';
    break;
  case 'simap-etudier':
    r.creer = { title: 'AO · ' + (jeton.t || 'simap ' + jeton.s), pipeline_id: IDS.pipeline_ao, stage_id: IDS.etape_ao_etudie, user_id: IDS.utilisateur_bureau,
      ...champs({ source: 'simap', source_detail: 'https://www.simap.ch/ (projet ' + jeton.s + ')' }) };
    r.activite = { subject: 'AO : télécharger le dossier et noter les dates (questions, visite, dépôt)', type: 'task', due_date: t.toISODate() };
    r.page = 'Affaire créée dans « Marchés publics », avec la première tâche.';
    break;
  case 'simap-ignorer': r.page = 'Ignoré. Rien d\'autre à faire.'; break;
  case 'b2b-interesse':
    r.maj = { stage_id: IDS.etape_b2b_interesse };
    r.activite = { subject: 'Envoyer le dossier de références et 2 fiches (e-mail individuel, voir le script)', type: 'email', due_date: t.toISODate(), deal_id: deal.id };
    r.page = 'Noté : « Intéressé ». Tâche créée pour l\'e-mail individuel (touche 3).';
    break;
  case 'b2b-rappeler':
    r.activite = { subject: 'Rappeler (prospection)', type: 'call', due_date: t.plus({ days: 7 }).toISODate(), deal_id: deal.id };
    r.page = 'Rappel planifié dans une semaine.';
    break;
  case 'b2b-pas-maintenant':
    r.maj = { stage_id: IDS.etape_b2b_pas_maintenant, ...champs({ recontact_le: t.plus({ months: 12 }).toISODate() }) };
    r.page = 'Noté : nouveau contact dans 12 mois.';
    break;
  case 'b2b-ne-plus':
    r.maj = { stage_id: IDS.etape_b2b_ne_plus, status: 'lost', lost_reason: 'Ne plus contacter', ...champs({ ne_pas_relancer: 'oui' }) };
    r.page = 'Noté : ce contact ne sera plus sollicité.';
    break;
}
return [{ json: { ...r, deal_id: deal ? deal.id : null, html: page('C\'est noté', '<p>' + r.page.replace(/</g, '&lt;').replace(/\n/g, '<br>') + '</p>') } }];
